/* @lc app=leetcode id=2741 lang=kotlin */ class Solution { fun specialPerm(nums: IntArray): Int = Array(1 shl nums.size) { IntArray(nums.size) }.also { dp -> nums.indices.forEach { i -> dp[1 shl i][i] = 1 } }.also { dp -> (1 until (1 shl nums.size)).forEach { m -> nums.indices.forEach { i -> if ((m and (1 shl i)) != 0) nums.indices.forEach { j -> if ((m and (1 shl j)) == 0 && (nums[i] % nums[j] == 0 || nums[j] % nums[i] == 0)) (m or (1 shl j)).let { nm -> dp[nm].also { it[j] = (it[j] + dp[m][i]) % 1000000007 } } } } } }.run { (this[(1 shl nums.size) - 1].fold(0L) { a, v -> (a + v) % 1000000007 }).toInt() } }